// Map old category strings → new slugs
function mapCategory(old: string): string {
  const map: Record<string, string> = {
    'API (ACTIVE)': 'api',
    'EXCIPIENT (PHARMA)': 'excipient-pharma',
    'VITAMIN': 'vitamin',
    'EXCIPIENT (FOOD)': 'excipient-food',
    'EXICIPIENT (TECHNICAL)': 'excipient-technical',
    'EXCIPIENT (TECHNICAL)': 'excipient-technical',
    'INTERMEDIATE': 'intermediate',
    'OTHER CHEMICALS': 'other',
    'MINERAL': 'mineral',
  }
  return map[old.trim()] ?? 'other'
}

