async function uploadFromFile(imageFile: string, bucket: string, destName: string): Promise<string | null> {
  const localPath = join(UPLOADS_DIR, imageFile)
  if (!existsSync(localPath)) {
    console.warn(`  ✗ Not found in scripts/uploads/: ${imageFile}`)
    return null
  }
  try {
    const buffer = readFileSync(localPath)
    const ext = imageFile.split('.').pop() ?? 'jpg'
    const mimeMap: Record<string, string> = {
      png: 'image/png', jpg: 'image/jpeg', jpeg: 'image/jpeg', webp: 'image/webp', gif: 'image/gif',
    }
    const contentType = mimeMap[ext.toLowerCase()] ?? 'application/octet-stream'
    const path = `${destName}.${ext}`
    const { error } = await supabase.storage.from(bucket).upload(path, buffer, { contentType, upsert: true })
    if (error) { console.warn(`  ✗ Storage error for ${path}:`, error.message); return null }
    return supabase.storage.from(bucket).getPublicUrl(path).data.publicUrl
  } catch (e) {
    console.warn(`  ✗ Upload failed for ${imageFile}:`, (e as Error).message)
    return null
  }
}

function makeSlug(name: string, used: Set<string>): string {
  let base = slugify(name.trim(), { lower: true, strict: true })
  if (!base) base = `product-${Math.random().toString(36).slice(2, 8)}`
  let slug = base, i = 1
  while (used.has(slug)) slug = `${base}-${i++}`
  used.add(slug)
  return slug
}

async function seed() {
  console.log('🌱 Alphachem seed starting...\n')

  // 1. Categories
  console.log('📂 Seeding categories...')
  const { data: cats, error: catErr } = await supabase
    .from('categories')
    .upsert(CATEGORIES, { onConflict: 'slug' })
    .select()
  if (catErr) { console.error('Category error:', catErr); process.exit(1) }
  const catMap = new Map(cats!.map((c: {slug: string; id: string}) => [c.slug, c.id]))
  console.log(`  ✓ ${cats!.length} categories\n`)

  // 2. Slider
  console.log('🖼️  Seeding slider images...')
  for (const s of SLIDER_FILES) {
    const publicUrl = await uploadFromFile(s.file, 'slider', `slide-${s.order}`)
    if (publicUrl) {
      await supabase.from('slider_images').upsert({ image_url: publicUrl, sort_order: s.order, active: true })
      console.log(`  ✓ slide-${s.order}`)
    }
  }
  console.log()

  // 3. Site content
  console.log('📝 Seeding site content...')
  await supabase.from('site_content').upsert([
    { key: 'about_text', locale: 'az', value: ABOUT.az },
    { key: 'about_text', locale: 'en', value: ABOUT.en },
    { key: 'about_text', locale: 'ru', value: ABOUT.ru },
    { key: 'contact_address_az', locale: 'az', value: 'Azərbaycan, Bakı şəhəri.' },
    { key: 'contact_address_az', locale: 'en', value: 'Azerbaijan, Baku' },
    { key: 'contact_address_az', locale: 'ru', value: 'Азербайджан, г. Баку' },
  ], { onConflict: 'key,locale' })
  console.log('  ✓ Site content\n')

  // 4. Products
  console.log('🧪 Seeding products...')
  const usedSlugs = new Set<string>()

  for (const p of PRODUCTS) {
    const catSlug = mapCategory(p.category)
    const catId = catMap.get(catSlug)
    const slug = makeSlug(p.titleAZ, usedSlugs)

    // Upload product image from local scripts/uploads/
    const storedUrl = await uploadFromFile(p.imageFile, 'products', `product-${p.id}`)

    const { data: product, error: prodErr } = await supabase
      .from('products')
      .upsert({ slug, category_id: catId, image_url: storedUrl, sort_order: p.id, active: true }, { onConflict: 'slug' })
      .select()
      .single()

    if (prodErr || !product) { console.warn(`  ✗ ${p.titleAZ}:`, prodErr?.message); continue }

    await supabase.from('product_translations').upsert([
      { product_id: product.id, locale: 'az', name: p.titleAZ.trim(), description: p.descAZ || null },
      { product_id: product.id, locale: 'en', name: p.titleEN.trim(), description: p.descEN || null },
      { product_id: product.id, locale: 'ru', name: p.titleRU.trim(), description: p.descRU || null },
    ], { onConflict: 'product_id,locale' })

    console.log(`  ✓ [${p.id}] ${p.titleAZ} → ${slug}`)
  }

  console.log('\n✅ Seed complete!')
}

seed().catch(console.error)
